INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Bedienfeld immer physisch?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch softwarebasiert sein"}, {"text": "Ja", "correct": false, "because": "Nicht auf Hardware beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel, wenn ich eine Benutzeroberfläche einrichte?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Fördert intuitive Nutzung"}, {"text": "Maximale Komplexität", "correct": false, "because": "Verwirrt Nutzer"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine solche Schnittstelle effektiv?', 5, '[{"text": "Klarheit", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Reaktionsschnelligkeit", "correct": true, "because": "Verbessert Nutzererlebnis"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Nicht primär"}, {"text": "Komplexe Animationen", "correct": false, "because": "Können ablenken"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Bedienfeld zeigt Systemstatus an. b) Es ersetzt die gesamte Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nur Schnittstelle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Gestaltung einer Benutzeroberfläche?', 4, '[{"text": "Nutzerfeedback", "correct": false, "because": "Verbessert Design"}, {"text": "Zugänglichkeit", "correct": false, "because": "Sichert Inklusion"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine solche Schnittstelle immer grafisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch textbasiert sein"}, {"text": "Ja", "correct": false, "because": "Textkonsolen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist entscheidend für ein Bedienfeld?', 3, '[{"text": "Intuitive Steuerung", "correct": true, "because": "Erleichtert Bedienung"}, {"text": "Hohe Rechenleistung", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Anpassung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen unterstützt eine solche Schnittstelle?', 5, '[{"text": "Konfiguration", "correct": true, "because": "Ermöglicht Systemsteuerung"}, {"text": "Statusanzeige", "correct": true, "because": "Zeigt Systemzustand"}, {"text": "Datenkompression", "correct": false, "because": "Andere Funktion"}, {"text": "Hardwarewartung", "correct": false, "because": "Physikalische Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bedienfelder verbessern die Interaktion. b) Sie sind immer touchscreenbasiert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Bedienfeld?', 4, '[{"text": "Benutzerinteraktion", "correct": false, "because": "Kern der Funktion"}, {"text": "Feedback-Mechanismus", "correct": false, "because": "Bestätigt Aktionen"}, {"text": "3D-Rendering", "correct": true, "because": "Nicht notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Bedienfelder nur für Administratoren?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für normale Nutzer"}, {"text": "Ja", "correct": false, "because": "Breite Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Schnittstellen gibt es?', 4, '[{"text": "Grafisch", "correct": true, "because": "Visuelle Steuerung"}, {"text": "Textbasiert", "correct": true, "because": "Befehlszeilen"}, {"text": "Netzwerkprotokolle", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Bedienfelder immer komplex sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können einfach gestaltet sein"}, {"text": "Ja", "correct": false, "because": "Komplexität variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Gestaltung einer Schnittstelle?', 3, '[{"text": "Benutzererlebnis", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Maximale Funktionen", "correct": false, "because": "Kann überladen"}, {"text": "Manuelle Eingaben", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bedienfelder ermöglichen Steuerung. b) Sie speichern Daten dauerhaft.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht primäre Funktion"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gutes Bedienfeld?', 5, '[{"text": "Effizienz", "correct": true, "because": "Vereinfacht Aufgaben"}, {"text": "Fehlerreduktion", "correct": true, "because": "Intuitive Bedienung"}, {"text": "Hohe Speicherung", "correct": false, "because": "Nicht relevant"}, {"text": "Automatische Updates", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Benutzeroberfläche unwichtig?', 3, '[{"text": "Lesbarkeit", "correct": false, "because": "Fördert Verständnis"}, {"text": "Reaktionszeit", "correct": false, "because": "Verbessert Nutzung"}, {"text": "Hintergrundmusik", "correct": true, "because": "Kein Funktionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordern Bedienfelder immer Hardware?', 3, '[{"text": "Nein", "correct": true, "because": "Softwarebasiert möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bedienfelder für alle Systeme geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Breit einsetzbar"}, {"text": "Nein", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Nutzung einer Benutzeroberfläche?', 4, '[{"text": "Serververwaltung", "correct": true, "because": "Vereinfacht Konfiguration"}, {"text": "Datenkompression", "correct": false, "because": "Hintergrundprozess"}, {"text": "Netzwerkprotokollierung", "correct": false, "because": "Andere Funktion"}]');
